'use strict';
window.quantumScene=function(stage){
 const k='<p class="edits-kicker">CONTROLLED QUANTUM ATTENTION · ICTAI 2026</p>';
 if(stage===0)return k+`<div class="edit-options"><button data-head="0" aria-pressed="true">Classical baseline</button><button data-head="1" aria-pressed="false">Replace one scorer</button></div><div class="quantum-heads"><div id="quantum-head-zero">Head 0<strong>Dot product</strong></div><div>Head 1<strong>Dot product</strong></div><div>Head 2<strong>Dot product</strong></div><div>Head 3<strong>Dot product</strong></div></div><p class="edits-note">Only one attention head’s scoring function changes. The surrounding transformer stays classical and matched across conditions.</p>${paperFigure('quantum-attention-architecture.png','View the transformer architecture')}`;
 if(stage===1)return k+`<div class="edit-options">${['None','Within registers','Across registers','Full'].map((x,i)=>`<button data-circuit="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><svg class="circuit-demo" viewBox="0 0 440 150" role="img" aria-label="Schematic query and key registers with selected CZ gate connections"><text x="8" y="45">Q</text><text x="8" y="115">K</text><path d="M40 30H420M40 60H420M40 100H420M40 130H420" stroke="#ccb9c3" fill="none"/><g id="circuit-gates" stroke="#e4b783" fill="#e4b783" stroke-width="3"></g></svg><p id="circuit-caption" class="edits-note">qnone: no two-qubit gates; query–key score is separable.</p>${paperFigure('quantum-circuit-modes.png','View the complete circuit and modes')}`;
 return k+`<div class="edit-options"><button data-qdata="0" aria-pressed="true">TREC-6</button><button data-qdata="1" aria-pressed="false">AG News</button></div><div id="quantum-results"></div><p class="edits-note">Primary experiment: accuracy %, mean ± standard deviation over five seeds (Table III). Neither non-separable condition significantly improves on classical. Simulated circuits; not demonstrated quantum advantage.</p>${paperFigure('quantum-attention-results.png','View entropy and qubit-width controls')}`;
};
window.bindQuantumScene=function(stage,scene,pause){
 function bind(attr,fn){scene.querySelectorAll('['+attr+']').forEach(b=>b.addEventListener('click',()=>{pause();scene.querySelectorAll('['+attr+']').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));fn(Number(b.getAttribute(attr)))}))}
 bind('data-head',i=>{const h=scene.querySelector('#quantum-head-zero');h.innerHTML='Head 0<strong>'+(i?'Quantum scorer':'Dot product')+'</strong>';h.classList.toggle('quantum-active',!!i)});
 bind('data-circuit',i=>{const pairs=[[],[[130,30,60],[280,100,130]],[[170,30,100],[290,60,130]],[[100,30,60],[210,60,100],[330,100,130]]][i];scene.querySelector('#circuit-gates').innerHTML=pairs.map(([x,y,z])=>`<line x1="${x}" x2="${x}" y1="${y}" y2="${z}"/><circle cx="${x}" cy="${y}" r="5"/><circle cx="${x}" cy="${z}" r="5"/>`).join('');scene.querySelector('#circuit-caption').textContent=['qnone: no two-qubit gates; query–key score is separable.','qintra: gates stay inside query or key registers; the query–key score remains separable.','qcross: cross-register gates permit a non-separable query–key score.','qfull: within- and cross-register connections permit a non-separable query–key score.'][i]});
 if(stage===2){function chart(i){const v=[[[82.4,1.1],[81.8,.7],[82.5,1.2],[83,1.4],[81.6,1.1]],[[77.1,.3],[77.1,.8],[76.2,.7],[77.1,.7],[76.6,1.3]]][i];scene.querySelector('#quantum-results').innerHTML=['Classical','qnone','qintra','qcross','qfull'].map((n,j)=>`<div class="quantum-result"><span>${n}</span><div class="bar-track"><div style="width:${v[j][0]}%"></div></div><b>${v[j][0].toFixed(1)} ± ${v[j][1].toFixed(1)}</b></div>`).join('')};chart(0);bind('data-qdata',chart)}
 scene.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)pause()}));
};
